#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define IN_R(A,B,L,R) max(0,min((B),(R))-max((A),(L))+1)

const ll M=998244353;
void run(){
    int n;
    cin>>n;
    vector<int>a(n+1);
    vector<vector<int>>pos(n+1);
    for(int i=1;i<=n;i++){
        cin>>a[i];
        pos[a[i]].push_back(i);
    }
    vector<ll> d(n+2,0);
    d[1]=1;
    for(int x=1;x<n;x++){
        vector<ll>nd(n+2,0);
        for(int l=1;l<=x;l++){
            if(!d[l])continue;
            for(int nl=l;nl<=l+1;++nl){
                bool ok=true;
                for(int i:pos[x]){
                    int p_cur=IN_R(1,i,l,l+n-x);
                    int p_nxt=IN_R(1,i,nl,nl+n-x-1);
                    bool p_v=(p_cur == i/2 +1) && (p_nxt<=i/2);
                    
                    int sl=n-i+1;
                    int s_cur=IN_R(i,n,l,l+n-x);
                    int s_nxt=IN_R(i,n,nl,nl+n-x-1);
                    bool s_v=(s_cur==sl/2+1)&& (s_nxt<=sl/2);
                    
                    if(!p_v && !s_v){
                        ok=false;
                        break;
                    }
                }
                if(ok)nd[nl]=(nd[nl]+d[l])%M;
            }
        }
        d=nd;
    } 


ll tot=0;
for(int l=1;l<=n;l++){
    if(!d[l])continue;
    bool ok=true;
    for(int i:pos[n]){
        int p_cur=IN_R(1,i,l,l);
        bool p_v=(p_cur==i/2+1);
        
        int sl=n-i+1;
        int s_cur=IN_R(i,n,l,l);
        bool s_v=(s_cur==sl/2+1);
        
        if(!p_v && !s_v){
            ok=false;
            break;
        }
        
    }
    if(ok)tot=(tot+d[l])%M;
}
cout<<tot<<endl;
}

int main(){
    int t;
    cin>>t;
    while(t--){
        run();
    }
}















